# The closure-compiler processes finish too quickly. Let me create a Java program that keeps running 
# so we can attach to it with SJK tools. We'll compile some closure-compiler source files first, 
# then run a longer process with JMX enabled.

# Let's create a simple Java program that loads the closure-compiler jar and does compilation in a loop
cat > /workspace/CompileLoop.java << 'JAVA'
import com.google.javascript.jscomp.*;

public class CompileLoop {
    public static void main(String[] args) throws Exception {
        System.out.println("Starting compile loop with closure-compiler...");
        String jsFile = args.length > 0 ? args[0] : "/workspace/sample.js";
        int iterations = args.length > 1 ? Integer.parseInt(args[1]) : 100;

        for (int i = 0; i < iterations; i++) {
            try {
                String[] compilerArgs = {
                    "--compilation_level=ADVANCED",
                    "--js=" + jsFile
                };
                com.google.javascript.jscomp.CommandLineRunner.main(compilerArgs);
                System.out.println("Iteration " + (i + 1) + " complete");
                Thread.sleep(500);
            } catch (Exception e) {
                System.err.println("Error in iteration " + (i + 1) + ": " + e.getMessage());
            }
        }
        System.out.println("All iterations complete.");
    }
}
JAVA
echo "Created CompileLoop.java"

# Compile it with the closure-compiler jar on classpath
javac -cp /workspace/closure-compiler.jar /workspace/CompileLoop.java 2>&1
echo "Compiled CompileLoop.java"

